/// 📐️ The most divisions one LOD band may submit as real line geometry. A finer band is DROPPED
/// rather than drawn at a distorted spacing — see [`append_lod_grid_lines`].
const WORLD_GRID_MAX_DIVISIONS: i32 = 512;

